};
export type HookHandler<Data> = ((a: CommonHookHandlerArg<Data>) => void)[];
export type LoadHandlerArg = CommonHookHandlerArg<{
    meta: YagrMeta;
}>;
export type OnSelectHandlerArg = CommonHookHandlerArg<{
    from: number;
    to: number;
}>;
export type ErrorHandlerArg = CommonHookHandlerArg<{
    type: YagrState['stage'];
    error: Error;
}>;
export type ProcessedHandlerArg = CommonHookHandlerArg<{
    meta: Pick<YagrMeta, 'processTime'>;
}>;
export type InitedHandlerArg = CommonHookHandlerArg<{
    meta: Pick<YagrMeta, 'initTime'>;
}>;
export type DisposeHandlerArg = CommonHookHandlerArg<{}>;
export type ResizeHandlerArg = CommonHookHandlerArg<{
    entries: ResizeObserverEntry[];
}>;
export type ScaleUpdateHandlerArg = CommonHookHandlerArg<{
    scales: Record<string, {
        min: number;
        max: number;
    }>;
}>;
export interface InternalYargHooks {
